*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #06080f;
  --surface: rgba(12, 18, 32, 0.85);
  --border: rgba(99, 179, 237, 0.15);
  --text: #e8edf5;
  --muted: #8899b0;
  --accent: #38bdf8;
  --accent2: #a78bfa;
  --gold: #fbbf24;
  --green: #34d399;
  --purple: #c084fc;
  --red: #f87171;
  --font: 'Outfit', system-ui, sans-serif;
  --mono: 'JetBrains Mono', monospace;
}

html, body { height: 100%; overflow-x: hidden; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

/* Cosmos background */
.cosmos { position: fixed; inset: 0; z-index: 0; pointer-events: none; }
.stars {
  position: absolute; inset: 0;
  background-image:
    radial-gradient(1px 1px at 10% 20%, rgba(255,255,255,.6) 0%, transparent 100%),
    radial-gradient(1px 1px at 30% 60%, rgba(255,255,255,.4) 0%, transparent 100%),
    radial-gradient(1.5px 1.5px at 70% 30%, rgba(255,255,255,.5) 0%, transparent 100%),
    radial-gradient(1px 1px at 90% 80%, rgba(255,255,255,.3) 0%, transparent 100%),
    radial-gradient(1px 1px at 50% 50%, rgba(255,255,255,.2) 0%, transparent 100%);
  background-size: 400px 400px;
  animation: drift 120s linear infinite;
}
.nebula {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 60% 40% at 20% 80%, rgba(56,189,248,.08) 0%, transparent 70%),
    radial-gradient(ellipse 50% 50% at 80% 20%, rgba(167,139,250,.07) 0%, transparent 70%);
}
@keyframes drift { to { background-position: 400px 400px; } }

/* Header */
.site-header {
  position: relative; z-index: 100;
  display: flex;
  align-items: center;
  gap: 1.25rem;
  padding: 0.85rem 2rem;
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(12px);
  background: rgba(6,8,15,.92);
  min-width: 0;
  overflow: visible;
}
.brand {
  display: flex;
  align-items: center;
  gap: .85rem;
  flex: 0 1 280px;
  min-width: 0;
  max-width: 300px;
}
.brand-text {
  min-width: 0;
  overflow: hidden;
}
.header-profile {
  width: 48px; height: 48px; border-radius: 50%; object-fit: cover;
  border: 2px solid rgba(251,191,36,.55);
  box-shadow: 0 0 18px rgba(251,191,36,.35), 0 0 0 3px rgba(56,189,248,.15);
  flex-shrink: 0;
}
.brand-icon { font-size: 2rem; filter: drop-shadow(0 0 12px rgba(251,191,36,.5)); }
.brand h1 {
  font-size: 1.4rem; font-weight: 700; letter-spacing: -.02em;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.brand p,
#node-breadcrumb {
  font-size: .8rem; color: var(--muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  max-width: 100%;
}

.header-cluster {
  flex: 1 1 auto;
  min-width: 0;
  display: grid;
  /* espaço | busca | espaço | tech | espaço | data */
  grid-template-columns: 1fr auto 1fr auto 1fr auto;
  align-items: center;
  column-gap: 0.75rem;
  overflow: visible;
}

/* Buttons */
.btn-primary, .btn-ghost {
  font-family: var(--font); font-size: .875rem; font-weight: 600;
  padding: .6rem 1.2rem; border-radius: 8px; cursor: pointer;
  transition: all .2s; border: none; text-decoration: none; display: inline-flex; align-items: center; gap: .4rem;
}
.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  color: #fff; box-shadow: 0 4px 20px rgba(56,189,248,.3);
}
.btn-primary:hover { transform: translateY(-1px); box-shadow: 0 6px 28px rgba(56,189,248,.45); }
.btn-ghost {
  background: transparent; color: var(--accent);
  border: 1px solid var(--border);
}
.btn-ghost:hover { background: rgba(56,189,248,.08); border-color: var(--accent); }

.header-nav {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: .5rem;
  flex-shrink: 0;
  grid-column: 6;
  justify-self: end;
  min-width: 0;
}
.header-datetime {
  font-family: var(--mono); font-size: .68rem; line-height: 1.4;
  color: var(--muted); text-align: right;
  padding: .4rem .7rem; border-radius: 8px;
  background: rgba(255,255,255,.04); border: 1px solid var(--border);
  display: flex; flex-direction: column; align-items: flex-end; gap: .1rem;
}
.header-datetime .dt-date { display: block; white-space: nowrap; }
.header-datetime .dt-time { display: block; color: var(--accent); font-weight: 600; white-space: nowrap; }
.header-nav .btn-ghost { white-space: nowrap; }

/* Núcleo tech 3D — centro entre busca e data */
.tech-dim-widget {
  position: relative;
  top: auto;
  right: auto;
  z-index: 5;
  grid-column: 4;
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  justify-self: center;
  width: 100px;
  min-width: 100px;
  max-width: 100px;
  height: 92px;
  margin: 0;
  pointer-events: none;
  perspective: 620px;
  perspective-origin: 50% 45%;
