  background: rgba(6, 8, 15, .88);
  border: 1px solid rgba(56, 189, 248, .45);
  box-shadow: inset 0 0 14px rgba(56, 189, 248, .12);
  backface-visibility: hidden;
}
.tech-cube-face.front  { transform: rotateY(0deg) translateZ(14px); }
