.tech-cube-face.right  { transform: rotateY(90deg) translateZ(14px); }
.tech-cube-face.left   { transform: rotateY(-90deg) translateZ(14px); }
.tech-cube-face.top    { transform: rotateX(90deg) translateZ(14px); }
.tech-cube-face.bottom { transform: rotateX(-90deg) translateZ(14px); }
.tech-dim-core {
  position: absolute;
  width: 8px;
  height: 8px;
  left: 50%;
