@router.post("/tenants", response_model=AuditorTenantResponse, status_code=status.HTTP_201_CREATED)
async def create_auditor_tenant(payload: AuditorTenantCreateRequest, user: User = Depends(require_admin)):
    from app.db_sync import SyncSession
    from app.services.audit_service import log_audit
    from app.services.phase20_service import create_auditor_tenant, list_auditor_tenants

    with SyncSession() as session:
        try:
            create_auditor_tenant(session, payload.org_id, payload.slug, payload.brand_name)
        except ValueError as exc:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc)) from exc
        log_audit(
            session,
            action="auditor.tenant.create",
            resource_type="auditor",
            user_id=user.id,
            username=user.username,
            details={"slug": payload.slug, "org_id": payload.org_id},
        )
        session.commit()
        rows = list_auditor_tenants(session)
    row = next(r for r in rows if r["slug"] == payload.slug)
    return row


