ALL_WIDGETS = [
    "stats",
    "status_chart",
    "type_breakdown",
    "fleet_metrics",
    "deep_coverage",
    "discovery",
    "devices",
    "events",
]

CUSTOM_TEMPLATES_PATH = Path(__file__).resolve().parents[2] / "data" / "custom_dashboard_templates.json"

# Templates corporativos por role / perfil operacional
DASHBOARD_TEMPLATES: dict[str, dict] = {
    "default": {
        "id": "default",
        "label": "Padrão SentinelAI",
        "scope": "default",
        "widgets": list(ALL_WIDGETS),
        "hidden": ["fleet_metrics", "deep_coverage"],
    },
    "role_admin": {
        "id": "role_admin",
        "label": "Admin (tudo visível)",
        "scope": "role",
        "widgets": list(ALL_WIDGETS),
        "hidden": [],
    },
    "role_operator": {
        "id": "role_operator",
        "label": "Operator (ops + discovery)",
        "scope": "role",
        "widgets": list(ALL_WIDGETS),
        "hidden": [],
    },
    "role_viewer": {
        "id": "role_viewer",
        "label": "Viewer (somente leitura)",
        "scope": "role",
        "widgets": list(ALL_WIDGETS),
        "hidden": ["discovery", "deep_coverage"],
    },
    "site_ops": {
        "id": "site_ops",
        "label": "Site / NOC (frota + cobertura)",
        "scope": "site",
        "widgets": list(ALL_WIDGETS),
        "hidden": ["discovery"],
    },
}


class DashboardLayoutPayload(BaseModel):
    widgets: list[str] = Field(default_factory=list)
    hidden: list[str] = Field(default_factory=list)


class DashboardTemplateInfo(BaseModel):
    id: str
    label: str
    scope: str
    widgets: list[str]
    hidden: list[str]
    custom: bool = False


class ApplyDashboardTemplateRequest(BaseModel):
    template_id: str = Field(..., min_length=1, max_length=64)


class DashboardTemplateCreate(BaseModel):
    id: str | None = Field(None, max_length=64)
    label: str = Field(..., min_length=1, max_length=120)
    scope: str = Field("custom", max_length=40)
    widgets: list[str] = Field(default_factory=list)
    hidden: list[str] = Field(default_factory=list)


class UserPreferencesPayload(BaseModel):
    preferred_site_id: int | None = None
    dashboard_template_id: str | None = None


def _role_template_id(role: str | None) -> str:
    key = f"role_{(role or 'viewer').lower()}"
    return key if key in DASHBOARD_TEMPLATES else "default"


def _slugify(label: str) -> str:
    s = re.sub(r"[^a-zA-Z0-9]+", "-", label.strip().lower()).strip("-")
    return (s or "custom")[:48]


def _load_custom_templates() -> dict[str, dict]:
    if not CUSTOM_TEMPLATES_PATH.is_file():
        return {}
    try:
        raw = json.loads(CUSTOM_TEMPLATES_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(raw, dict):
        return {}
    out: dict[str, dict] = {}
    for tid, t in raw.items():
        if not isinstance(t, dict):
            continue
        out[str(tid)] = {
            "id": str(t.get("id") or tid),
            "label": str(t.get("label") or tid),
            "scope": str(t.get("scope") or "custom"),
            "widgets": [str(x) for x in (t.get("widgets") or ALL_WIDGETS)],
            "hidden": [str(x) for x in (t.get("hidden") or [])],
            "custom": True,
        }
    return out


def _save_custom_templates(data: dict[str, dict]) -> None:
    CUSTOM_TEMPLATES_PATH.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        tid: {
            "id": t["id"],
            "label": t["label"],
            "scope": t.get("scope") or "custom",
            "widgets": t.get("widgets") or [],
            "hidden": t.get("hidden") or [],
        }
        for tid, t in data.items()
    }
    CUSTOM_TEMPLATES_PATH.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def _all_templates() -> dict[str, dict]:
    merged = {**DASHBOARD_TEMPLATES}
    for tid, t in _load_custom_templates().items():
        merged[tid] = t
    return merged


