@router.post("/devices/{device_id}/poll")
async def zion_poll_device(device_id: int, _: User = Depends(require_operator)):
    """Dispara coleta SNMP/WMI assíncrona para um host (empty-state CTA)."""
    from app.db_sync import SyncSession
    from app.models import Device, DeviceStatus
    from app.services.zion_panels import queue_zion_metrics_refresh, refresh_device_sensor_metrics

    with SyncSession() as session:
        device = session.get(Device, device_id)
        if not device or device.status == DeviceStatus.RETIRED:
            raise HTTPException(status_code=404, detail="Dispositivo não encontrado")
        queued = queue_zion_metrics_refresh(device_ids=[device_id])
        if not queued:
            # Fallback síncrono se Celery indisponível
            result = refresh_device_sensor_metrics(session, device, force=True)
            session.commit()
            return {"queued": False, "device_id": device_id, "result": result}
        return {"queued": True, "device_id": device_id}

