        "api_key": settings.copilot_llm_api_key or ("ollama" if provider == "ollama" else ""),
        "max_tokens": settings.copilot_llm_max_tokens,
    }


def llm_available() -> bool:
    if not settings.copilot_llm_enabled:
        return False
    cfg = resolve_llm_config()
    if cfg["provider"] == "ollama":
        return True
    return bool(cfg["api_key"])


def _http_timeout() -> httpx.Timeout:
    return httpx.Timeout(
        connect=float(getattr(settings, "copilot_llm_connect_timeout", 5.0)),
        read=float(getattr(settings, "copilot_llm_read_timeout", 60.0)),
        write=30.0,
        pool=5.0,
    )


async def _acquire_rate_slot() -> bool:
    """Sliding window: max N requests / 60s. Retorna False se excedeu."""
    limit = int(getattr(settings, "copilot_llm_rate_limit_per_minute", 30) or 30)
    if limit <= 0:
        return True
    now = time.monotonic()
    async with _RATE_LOCK:
        while _RATE_HITS and now - _RATE_HITS[0] > 60.0:
            _RATE_HITS.popleft()
        if len(_RATE_HITS) >= limit:
            logger.warning("LLM rate limit atingido (%s/min)", limit)
            return False
        _RATE_HITS.append(now)
        return True


async def achat_completion_messages(
    messages: list[dict[str, str]],
    *,
    temperature: float = 0.3,
) -> str | None:
    if not llm_available():
        return None
    if not await _acquire_rate_slot():
        return None

    cfg = resolve_llm_config()
    url = f"{cfg['base_url']}/chat/completions"
    headers = {"Content-Type": "application/json"}
    if cfg["api_key"]:
        headers["Authorization"] = f"Bearer {cfg['api_key']}"

    payload = {
        "model": cfg["model"],
        "messages": messages,
        "max_tokens": cfg["max_tokens"],
        "temperature": temperature,
    }
    try:
        async with httpx.AsyncClient(timeout=_http_timeout()) as client:
            resp = await client.post(url, headers=headers, json=payload)
        if resp.status_code == 429:
            logger.warning("LLM rate-limited by provider (429)")
            return None
        if resp.status_code >= 500:
            logger.warning("LLM server error %s: %s", resp.status_code, resp.text[:300])
            return None
        if resp.status_code != 200:
            logger.warning("LLM API error %s: %s", resp.status_code, resp.text[:300])
            return None
        data = resp.json()
        content = data["choices"][0]["message"]["content"]
        return (content or "").strip() or None
    except Exception as exc:
        logger.warning("LLM request failed: %s", exc)
        return None


def chat_completion_messages(messages: list[dict[str, str]], *, temperature: float = 0.3) -> str | None:
    """Wrapper sync para Celery / callers legados."""
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None
    if loop and loop.is_running():
        # Evita deadlock: cria task em thread com loop próprio
        import concurrent.futures

        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            return pool.submit(
                lambda: asyncio.run(achat_completion_messages(messages, temperature=temperature))
            ).result(timeout=90)
    return asyncio.run(achat_completion_messages(messages, temperature=temperature))


def chat_completion(system_prompt: str, user_message: str) -> str | None:
    return chat_completion_messages(
        [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ]
    )


async def achat_completion(system_prompt: str, user_message: str) -> str | None:
    return await achat_completion_messages(
        [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ]
    )


