from app.models import Alert, AlertStatus, AnomalyRecord, Device, DeviceStatus, Event, EventSeverity


def build_noc_context(session: Session) -> dict:
    since = datetime.now(UTC) - timedelta(hours=24)
    total = session.execute(select(func.count(Device.id))).scalar() or 0
    offline = session.execute(
        select(func.count(Device.id)).where(Device.status == DeviceStatus.INACTIVE)
    ).scalar() or 0
    critical_events = session.execute(
        select(Event)
        .where(Event.created_at >= since, Event.severity == EventSeverity.CRITICAL)
        .order_by(Event.created_at.desc())
        .limit(5)
    ).scalars().all()
    pending_alerts = session.execute(
        select(func.count(Alert.id)).where(Alert.status == AlertStatus.PENDING)
    ).scalar() or 0
    anomalies = session.execute(
        select(func.count(AnomalyRecord.id)).where(AnomalyRecord.is_resolved.is_(False))
    ).scalar() or 0
    return {
        "devices_total": total,
        "devices_offline": offline,
        "pending_alerts": pending_alerts,
        "active_anomalies": anomalies,
        "recent_critical": [
            {
                "type": e.event_type,
                "message": sanitize_event_message(e.message),
                "at": e.created_at.isoformat(),
            }
            for e in critical_events
        ],
    }


