import json
import logging
from typing import Any

import httpx
from sqlalchemy import select

from app.config import settings

logger = logging.getLogger(__name__)


def _send_expo(messages: list[dict], headers: dict) -> tuple[bool, list[str]]:
    stale: list[str] = []
    ok_count = 0
    with httpx.Client(timeout=15) as client:
        response = client.post(
            "https://exp.host/--/api/v2/push/send",
            json=messages,
            headers=headers,
        )
        if response.status_code != 200:
            logger.error("Expo push failed (%s): %s", response.status_code, response.text[:300])
            return False, stale
        payload = response.json()
        data = payload.get("data") if isinstance(payload, dict) else None
        results = data if isinstance(data, list) else [data] if data else []
        for msg, result in zip(messages, results):
            if not isinstance(result, dict):
                continue
            if str(result.get("status") or "") == "ok":
                ok_count += 1
                continue
            details = str(result.get("details") or result.get("message") or "")
            if "DeviceNotRegistered" in details or "not a registered push token" in details.lower():
                stale.append(str(msg.get("to") or ""))
    return ok_count > 0 or not stale, stale


def _send_web_push(subscription_json: str, subject: str, body: str, data: dict[str, Any] | None) -> tuple[bool, bool]:
    """Retorna (ok, stale). stale=True se a subscription deve ser removida."""
    if not settings.vapid_private_key or not settings.vapid_public_key:
        logger.info("VAPID não configurado — skip web push")
        return False, False
    try:
        from pywebpush import WebPushException, webpush
    except ImportError:
        logger.error("pywebpush não instalado")
        return False, False

    try:
        subscription = json.loads(subscription_json)
    except json.JSONDecodeError:
        logger.error("Subscription web push inválida")
        return False, True

    payload = {"title": subject[:100], "body": body[:240], **(data or {})}
    if "url" not in payload:
        payload["url"] = "/#/alerts"

    try:
        webpush(
            subscription_info=subscription,
            data=json.dumps(payload),
            vapid_private_key=settings.vapid_private_key,
            vapid_claims={"sub": settings.vapid_subject or "mailto:admin@sentinelai.local"},
        )
        return True, False
    except WebPushException as exc:
        status = getattr(getattr(exc, "response", None), "status_code", None)
        logger.error("Web push failed: %s", exc)
        if status in (404, 410):
            return False, True
        return False, False
    except Exception as exc:
        logger.error("Web push error: %s", exc)
        return False, False


def send_push_alert(
    subject: str,
    body: str,
    *,
    user_id: int | None = None,
    data: dict[str, Any] | None = None,
) -> bool:
    """Envia alerta via Expo e/ou Web Push (VAPID). Remove tokens inválidos."""
    from app.db_sync import SyncSession
    from app.models import PushToken

    deep = dict(data or {})
    if "url" not in deep:
        deep["url"] = "/#/alerts"

    with SyncSession() as session:
        query = select(PushToken)
        if user_id is not None:
            query = query.where(PushToken.user_id == user_id)
        rows = list(session.execute(query).scalars().all())
        if not rows:
            logger.info("Nenhum push token registrado. Alerta: %s", subject)
            return False

        expo_rows = [r for r in rows if (r.platform or "").startswith("expo")]
        web_rows = [r for r in rows if (r.platform or "") == "web"]
        any_ok = False
        stale_tokens: list[str] = []

        if expo_rows:
            messages = [
                {
                    "to": row.token,
                    "title": subject[:100],
                    "body": body[:240],
                    "sound": "default",
                    "data": deep,
                }
                for row in expo_rows
            ]
            headers = {"Content-Type": "application/json"}
            if settings.expo_push_access_token:
                headers["Authorization"] = f"Bearer {settings.expo_push_access_token}"
            try:
                ok, stale = _send_expo(messages, headers)
                any_ok = any_ok or ok
                stale_tokens.extend(stale)
            except Exception as exc:
                logger.error("Expo push error: %s", exc)

        for row in web_rows:
            ok, stale = _send_web_push(row.token, subject, body, deep)
            any_ok = any_ok or ok
            if stale:
                stale_tokens.append(row.token)

        if stale_tokens:
            for token in stale_tokens:
                stale = session.execute(select(PushToken).where(PushToken.token == token)).scalar_one_or_none()
                if stale:
                    session.delete(stale)
            session.commit()

        return any_ok

from datetime import UTC, datetime, timedelta

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.config import settings
from app.models import Alert, AlertChannelConfig, AlertSilence, AlertStatus, Event, EventSeverity

_SEVERITY_RANK = {
    EventSeverity.INFO: 0,
    EventSeverity.WARNING: 1,
    EventSeverity.CRITICAL: 2,
    "info": 0,
    "warning": 1,
    "critical": 2,
}


def _severity_value(severity: EventSeverity | str) -> int:
    if isinstance(severity, EventSeverity):
        return _SEVERITY_RANK.get(severity, 0)
    return _SEVERITY_RANK.get(str(severity).lower(), 0)


def matching_rules(session: Session, event: Event) -> list:
    from app.models import AlertRule

    rules = session.execute(
        select(AlertRule).where(AlertRule.is_enabled.is_(True)).order_by(AlertRule.id)
    ).scalars().all()
    matched: list = []
    event_sev = _severity_value(event.severity)
    for rule in rules:
        if rule.event_type and rule.event_type != event.event_type:
            continue
        if event_sev < _severity_value(rule.min_severity):
            continue
        matched.append(rule)
    return matched


def is_event_silenced(session: Session, event: Event) -> bool:
    now = datetime.now(UTC)
    rows = session.execute(
        select(AlertSilence).where(
            AlertSilence.event_type == event.event_type,
            AlertSilence.silenced_until > now,
        )
    ).scalars().all()
    for row in rows:
        if row.device_id is None:
            return True
        if event.device_id is not None and row.device_id == event.device_id:
            return True
    return False


def is_duplicate_suppressed(session: Session, event: Event) -> bool:
    """Suppress re-queue when same (event_type, device_id) already alerted recently."""
    minutes = int(settings.alert_suppress_repeat_minutes or 0)
    if minutes <= 0:
        return False
    since = datetime.now(UTC) - timedelta(minutes=minutes)
    stmt = (
        select(Alert.id)
        .join(Event, Event.id == Alert.event_id)
        .where(
            Event.event_type == event.event_type,
            Alert.created_at >= since,
            Alert.status.in_([AlertStatus.PENDING, AlertStatus.SENT]),
        )
        .limit(1)
    )
    if event.device_id is None:
        stmt = stmt.where(Event.device_id.is_(None))
    else:
        stmt = stmt.where(Event.device_id == event.device_id)
    # Allow current event's own rows (idempotent re-queue); only suppress other events
    stmt = stmt.where(Event.id != event.id)
    return session.execute(stmt).first() is not None


def channels_for_event(session: Session, event: Event) -> list[str]:
    """Resolve alert channels: matching rules override global defaults when any rule matches."""
    rules = matching_rules(session, event)
    if rules:
        channels: list[str] = []
        for rule in rules:
            for ch in rule.channels or []:
                ch_norm = str(ch).strip().lower()
                if ch_norm and ch_norm not in channels:
                    channels.append(ch_norm)
        if channels:
            return channels
    return settings.enabled_alert_channels


def delivery_targets_for_event(session: Session, event: Event) -> list[dict]:
    rules = matching_rules(session, event)
    if rules:
        targets: list[dict] = []
        seen: set[tuple[str, int | None, str | None]] = set()
