def _fernet() -> Fernet:
    raw = (settings.backup_encryption_key or "").strip()
    if raw:
        try:
            return Fernet(raw.encode() if isinstance(raw, str) else raw)
        except Exception:
            pass
    digest = hashlib.sha256(settings.secret_key.encode("utf-8")).digest()
    key = base64.urlsafe_b64encode(digest)
    return Fernet(key)


def encrypt_bytes(data: bytes) -> bytes:
    return _fernet().encrypt(data)


def decrypt_bytes(data: bytes) -> bytes:
    try:
        return _fernet().decrypt(data)
    except InvalidToken as exc:
        raise ValueError("Falha ao descriptografar artefato — chave inválida") from exc


def compress_bytes(data: bytes) -> bytes:
    return gzip.compress(data, compresslevel=6)


def decompress_bytes(data: bytes) -> bytes:
    return gzip.decompress(data)


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def chain_hash(prev: str | None, content_sha: str) -> str:
    material = f"{prev or 'GENESIS'}|{content_sha}".encode()
    return sha256_hex(material)


def ensure_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)


def repo_disk_usage(path: Path) -> dict[str, int | float]:
    ensure_dir(path)
    total = 0
    for root, _, files in os.walk(path):
        for name in files:
            try:
                total += (Path(root) / name).stat().st_size
            except OSError:
                continue
    usage = shutil.disk_usage(path)
    return {
        "used_bytes": total,
        "free_bytes": int(usage.free),
        "total_bytes": int(usage.total),
        "used_pct": round(100.0 * (1 - usage.free / usage.total), 2) if usage.total else 0.0,
    }


def bootstrap_repositories(session: Session) -> list[BackupRepository]:
    existing = session.execute(select(BackupRepository)).scalars().all()
    if existing:
        return list(existing)
    defs = [
        ("Primary", "primary", settings.backup_repo_path),
        ("Secondary", "secondary", settings.backup_repo_secondary_path),
        ("Offsite", "offsite", settings.backup_repo_offsite_path),
    ]
    rows = []
    for name, kind, path in defs:
        ensure_dir(Path(path))
        row = BackupRepository(name=name, kind=kind, path=path, is_active=True)
