def sync_federation_peer(session: Session, peer_id: int) -> dict:
    from datetime import UTC, datetime

    peer = session.get(FederatedPeer, peer_id)
    if not peer:
        return {"success": False, "message": "Peer não encontrado"}
    try:
        with httpx.Client(timeout=8) as client:
            resp = client.get(f"{peer.api_url.rstrip('/')}/health")
        if resp.status_code == 200:
            peer.status = "online"
            peer.last_sync_at = datetime.now(UTC)
            session.add(peer)
            return {"success": True, "message": f"Peer {peer.name} online", "health": resp.json()}
        peer.status = "degraded"
        session.add(peer)
        return {"success": False, "message": f"HTTP {resp.status_code}"}
    except Exception as exc:
        peer.status = "offline"
        session.add(peer)
        return {"success": False, "message": str(exc)}


