@celery_app.task(name="app.workers.tasks.resolve_unknown_statuses")
def resolve_unknown_statuses(limit: int = 40, on_map_only: bool = True) -> dict:
    """Destrava cards em 'Aguardando ping…' com ping forçado (prioriza devices no mapa)."""
    from app.models import Device, DeviceStatus, TopologyLayout
    from app.services.monitor_service import ping_device_now

    with SyncSession() as session:
        query = (
            select(Device.id)
            .where(Device.status == DeviceStatus.UNKNOWN)
            .order_by(Device.id.asc())
        )
        if on_map_only:
            query = query.join(TopologyLayout, TopologyLayout.device_id == Device.id)
        device_ids = list(session.execute(query.limit(max(1, min(limit, 120)))).scalars().all())
        session.commit()

    resolved = 0
    failed = 0
    results: list[dict] = []
    for device_id in device_ids:
        try:
            with SyncSession() as session:
                result = ping_device_now(session, device_id, timeout=2)
                session.commit()
                if result.get("ok"):
                    resolved += 1
                    results.append(
                        {
                            "device_id": device_id,
                            "status": result.get("status"),
                            "alive": result.get("alive"),
                        }
                    )
                else:
                    failed += 1
        except Exception:
            failed += 1

    return {
        "candidates": len(device_ids),
        "resolved": resolved,
        "failed": failed,
        "sample": results[:10],
    }


@celery_app.task(name="app.workers.tasks.run_all_monitors")
def run_all_monitors() -> dict:
    """Ping/checks por monitor com commit curto — não segura locks durante a rede."""
    import redis

    from app.config import settings

    # Evita empilhar vários ciclos enquanto o anterior ainda pinga a frota
    lock_key = "sentinelai:lock:run_all_monitors"
    client = redis.Redis.from_url(settings.redis_url, decode_responses=True)
    if not client.set(lock_key, "1", nx=True, ex=600):
        return {"checked": 0, "skipped": 0, "alerts_processed": 0, "locked": True}

    try:
        with SyncSession() as session:
            monitor_ids = list(
                session.execute(select(Monitor.id).where(Monitor.is_enabled.is_(True))).scalars().all()
            )
            session.commit()

        checked = 0
        skipped = 0
        for monitor_id in monitor_ids:
            try:
                with SyncSession() as session:
                    monitor = session.get(Monitor, monitor_id)
                    if not monitor or not monitor.is_enabled:
                        skipped += 1
                        session.commit()
                        continue
                    if run_monitor_check(session, monitor):
                        checked += 1
                    else:
                        skipped += 1
                    session.commit()
            except Exception:
                # Um host lento/offline não pode bloquear o ciclo inteiro
                skipped += 1

        with SyncSession() as session:
            alerts_sent = process_pending_alerts(session)
            session.commit()
        return {"checked": checked, "skipped": skipped, "alerts_processed": alerts_sent}
    finally:
        try:
            client.delete(lock_key)
        except Exception:
            pass



@celery_app.task(name="app.workers.tasks.process_alerts")
def process_alerts_task() -> dict:
    with SyncSession() as session:
        count = process_pending_alerts(session)
        session.commit()
    return {"processed": count}


