from __future__ import annotations

import json
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://127.0.0.1:8000"

DEVICES = [
    {"ip": "192.168.77.1", "type": "router", "color": "#3b82f6", "x": 100, "y": 100},
    {"ip": "192.168.77.2", "type": "access_point", "color": "#f59e0b", "x": 300, "y": 100},
    {"ip": "192.168.77.3", "type": "server", "color": "#22c55e", "x": 500, "y": 100},
]

DELETE_IP = "192.168.77.2"  # access point


def req(method: str, path: str, token: str | None = None, body: dict | None = None) -> tuple[int, object]:
    headers = {"Content-Type": "application/json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    data = json.dumps(body).encode() if body is not None else None
    request = urllib.request.Request(f"{BASE}{path}", data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=15) as resp:
            raw = resp.read().decode()
            return resp.status, json.loads(raw) if raw else None
    except urllib.error.HTTPError as e:
        raw = e.read().decode()
        try:
            payload = json.loads(raw) if raw else raw
        except json.JSONDecodeError:
            payload = raw
        return e.code, payload


def login() -> str:
    form = urllib.parse.urlencode({"username": "admin", "password": "admin123"}).encode()
    request = urllib.request.Request(
        f"{BASE}/api/auth/login",
        data=form,
        headers={"Content-Type": "application/x-www-form-urlencoded"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=15) as resp:
        data = json.loads(resp.read().decode())
    return data["access_token"]


def graph_nodes(token: str) -> list[dict]:
    _, payload = req("GET", "/api/topology/graph?map_layer=physical", token)
    assert isinstance(payload, dict)
    return payload.get("nodes", [])


def cleanup(token: str) -> None:
    _, devices = req("GET", "/api/devices?include_retired=true", token)
    if not isinstance(devices, list):
        return
    for d in devices:
        ip = d.get("ip_address", "")
        if ip.startswith("192.168.77."):
            req("DELETE", f"/api/devices/{d['id']}", token)


def run() -> int:
    errors: list[str] = []

    try:
        token = login()
    except Exception as e:
        print("FAIL: login", e)
        return 1

    cleanup(token)

    created_ids: dict[str, int] = {}
    for spec in DEVICES:
        status, payload = req(
            "POST",
            "/api/topology/devices",
            token,
            {
                "ip_address": spec["ip"],
                "device_type": spec["type"],
                "x": spec["x"],
                "y": spec["y"],
                "map_layer": "physical",
            },
        )
        if status != 201:
            errors.append(f"add {spec['type']} ({spec['ip']}): HTTP {status} {payload}")
            continue
        if isinstance(payload, dict):
            created_ids[spec["ip"]] = payload["device_id"]

    nodes = graph_nodes(token)
    on_map = {n["ip_address"]: n for n in nodes if n.get("ip_address", "").startswith("192.168.77.")}

    if len(on_map) != 3:
        errors.append(f"esperado 3 no graph após add, veio {len(on_map)}: {list(on_map.keys())}")

    for spec in DEVICES:
        node = on_map.get(spec["ip"])
        if not node:
            errors.append(f"{spec['ip']} ausente no graph")
            continue
        if node.get("device_type") != spec["type"]:
            errors.append(f"{spec['ip']}: tipo {node.get('device_type')} != {spec['type']}")
        pos = node.get("position") or {}
        if pos.get("x") != spec["x"] or pos.get("y") != spec["y"]:
            errors.append(f"{spec['ip']}: posição errada {pos}")

    delete_id = created_ids.get(DELETE_IP)
    if not delete_id:
        errors.append(f"sem id para deletar {DELETE_IP}")
    else:
        status, _ = req("DELETE", f"/api/devices/{delete_id}", token)
        if status != 204:
            errors.append(f"delete {DELETE_IP}: HTTP {status}")

    # Simula Ctrl+F5 — nova leitura do servidor
    nodes_after = graph_nodes(token)
    ips_after = [n["ip_address"] for n in nodes_after if n.get("ip_address", "").startswith("192.168.77.")]

    if DELETE_IP in ips_after:
        errors.append(f"{DELETE_IP} VOLTOU após delete (simula F5)")
    if len(ips_after) != 2:
        errors.append(f"esperado 2 após delete, veio {len(ips_after)}: {ips_after}")

    for ip in ("192.168.77.1", "192.168.77.3"):
        if ip not in ips_after:
            errors.append(f"{ip} sumiu indevidamente após delete do AP")

    cleanup(token)

    # Cores esperadas (mesma fonte do frontend deviceTypes.ts)
    expected_colors = {d["type"]: d["color"] for d in DEVICES}
    frontend_ok = True
    for t, hex_color in expected_colors.items():
        if not hex_color.startswith("#") or len(hex_color) != 7:
            errors.append(f"cor inválida para {t}: {hex_color}")
            frontend_ok = False

    if errors:
        for e in errors:
            print("FAIL:", e)
        return 1

    print("OK: 3 devices no mapa com tipos/posições corretos")
    print("OK: delete AP -> restam router + server")
    print("OK: simula F5 -> deletado NÃO voltou")
    print("OK: cores ícone -> router #3b82f6, AP #f59e0b, server #22c55e (borda no DeviceNode.tsx)")
    return 0


if __name__ == "__main__":
    sys.exit(run())

