const CACHE = "sentinelai-v2";
const ASSETS = ["/", "/manifest.json"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)));
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))),
    ).then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  event.respondWith(
    fetch(event.request)
      .then((response) => response)
      .catch(() => caches.match(event.request)),
  );
});

self.addEventListener("push", (event) => {
  let title = "SentinelAI";
  let body = "Novo alerta";
  let url = "/#/alerts";
  let extra = {};
  try {
    const data = event.data ? event.data.json() : {};
    if (data && typeof data === "object") {
      if (data.title) title = String(data.title);
      if (data.body) body = String(data.body);
      if (data.url) url = String(data.url);
      extra = {
        event_type: data.event_type ?? null,
        device_id: data.device_id ?? null,
        alert_id: data.alert_id ?? null,
        event_id: data.event_id ?? null,
      };
    }
  } catch {
    try {
      body = event.data ? event.data.text() : body;
    } catch {
      /* ignore */
    }
  }
  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon: "/favicon.ico",
      badge: "/favicon.ico",
      data: { url, ...extra },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/#/alerts";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if ("focus" in client) {
          client.navigate?.(target);
          return client.focus();
        }
      }
      if (self.clients.openWindow) return self.clients.openWindow(target);
      return undefined;
    }),
  );
});

import { useEffect, useState, type ReactNode } from "react";
import { clearToken, fetchMe, fetchOidcLogout, getToken, setToken } from "./api/client";
import AppShell, { type AppPage } from "./components/layout/AppShell";
import { ErrorBoundary } from "./components/ErrorBoundary";
import { ThemeProvider } from "./context/ThemeProvider";
import { AuthProvider } from "./context/AuthContext";
import ChangePasswordPage from "./pages/ChangePasswordPage";
import Dashboard from "./pages/Dashboard";
import LoginPage from "./pages/LoginPage";
import ScannerPage from "./pages/ScannerPage";
import TopologyMap from "./pages/TopologyMap";
import AlertsPage from "./pages/AlertsPage";
import ReportsPage from "./pages/ReportsPage";
import InfrastructurePage from "./pages/InfrastructurePage";
import NocCopilotPage from "./pages/NocCopilotPage";
import ChatbotPage from "./pages/ChatbotPage";
import PlatformPage from "./pages/PlatformPage";
import UsersPage from "./pages/UsersPage";
import ZionPage from "./pages/ZionPage";
import WallboardPage from "./pages/WallboardPage";
import BackupPage from "./pages/BackupPage";
import ZionVMPage from "./pages/ZionVMPage";
import PublicWallboardPage, { isPublicWallboardRoute } from "./pages/PublicWallboardPage";

export default function App() {
  const [page, setPage] = useState<AppPage>("dashboard");
  const [authenticated, setAuthenticated] = useState(Boolean(getToken()));
  const [mustChangePassword, setMustChangePassword] = useState(false);
  const [booting, setBooting] = useState(true);
  const [publicWallboard, setPublicWallboard] = useState(isPublicWallboardRoute());
  const [ssoMfaToken, setSsoMfaToken] = useState<string | null>(null);
  const [ssoError, setSsoError] = useState<string | null>(null);
  const [alertDeepLink, setAlertDeepLink] = useState<Record<string, string>>({});

  function parseAppHash() {
    const raw = window.location.hash.replace(/^#\/?/, "");
    const [pathPart, queryPart] = raw.split("?");
    const path = (pathPart || "").toLowerCase();
    const params = new URLSearchParams(queryPart || "");
    if (path === "alerts" || path.startsWith("alerts")) {
      setPage("alerts");
      const link: Record<string, string> = {};
      for (const key of ["alert_id", "event_type", "device_id", "event_id"]) {
        const v = params.get(key);
        if (v) link[key] = v;
      }
      setAlertDeepLink(link);
    } else if (path === "topology" || path === "mapa" || path === "map") {
      setPage("topology");
    }
    setPublicWallboard(isPublicWallboardRoute());
  }

  useEffect(() => {
    parseAppHash();
    const onHash = () => parseAppHash();
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  useEffect(() => {
    // Consumir redirect OIDC (?sso_token= / ?sso_error= / ?sso_mfa_token=)
    const params = new URLSearchParams(window.location.search);
    const token = params.get("sso_token");
    const err = params.get("sso_error");
    const mfa = params.get("sso_mfa_token");
    if (token || err || mfa) {
      params.delete("sso_token");
      params.delete("sso_error");
      params.delete("sso_mfa_token");
      const qs = params.toString();
      const next = `${window.location.pathname}${qs ? `?${qs}` : ""}${window.location.hash}`;
      window.history.replaceState({}, "", next);
    }
    if (token) {
      setToken(token);
    }
    if (mfa) {
      setSsoMfaToken(mfa);
    }
    if (err) {
      setSsoError(err);
    }
  }, []);

  useEffect(() => {
    if (publicWallboard) {
      setBooting(false);
      return;
    }
    if (!getToken()) {
      setBooting(false);
      return;
    }
    fetchMe()
      .then((me) => {
        setAuthenticated(true);
        setMustChangePassword(Boolean(me.must_change_password));
      })
      .catch(() => {
        clearToken();
        setAuthenticated(false);
        setMustChangePassword(false);
      })
      .finally(() => setBooting(false));
  }, [publicWallboard]);

  // AuthProvider sempre no topo: evita "useAuth must be used within AuthProvider"
  // em HMR, ErrorBoundary retry e rotas que montam AppShell/páginas com o hook.
  let body: ReactNode;
  if (publicWallboard) {
    body = <PublicWallboardPage />;
  } else if (booting) {
    body = (
      <div className="sa-loading-row">
        <span className="sa-spinner" />
        <span>A verificar sessão...</span>
      </div>
    );
  } else if (!authenticated) {
    body = (
      <LoginPage
        initialMfaToken={ssoMfaToken}
        initialError={ssoError}
        onLogin={(opts) => {
          setAuthenticated(true);
          setMustChangePassword(Boolean(opts?.must_change_password));
          setSsoMfaToken(null);
          setSsoError(null);
        }}
      />
    );
  } else if (mustChangePassword) {
    body = <ChangePasswordPage onDone={() => setMustChangePassword(false)} />;
  } else {
    body = (
      <AppShell
        page={page}
        onNavigate={setPage}
        onLogout={() => {
          clearToken();
          setAuthenticated(false);
          setMustChangePassword(false);
          void fetchOidcLogout()
            .then((r) => {
              if (r.logout_url) window.location.assign(r.logout_url);
            })
            .catch(() => undefined);
        }}
      >
        <ErrorBoundary key={page}>
          {page === "dashboard" && <Dashboard />}
          {page === "topology" && <TopologyMap />}
          {page === "scanner" && <ScannerPage />}
          {page === "reports" && <ReportsPage />}
          {page === "copilot" && <NocCopilotPage />}
          {page === "chatbot" && <ChatbotPage />}
          {page === "alerts" && (
            <AlertsPage
              deepLink={alertDeepLink}
              onClearDeepLink={() => {
                setAlertDeepLink({});
                if (window.location.hash.toLowerCase().includes("alerts")) {
                  window.history.replaceState({}, "", `${window.location.pathname}${window.location.search}`);
                }
              }}
            />
          )}
          {page === "infra" && <InfrastructurePage />}
          {page === "platform" && <PlatformPage />}
          {page === "users" && <UsersPage />}
          {page === "zion" && <ZionPage />}
          {page === "wallboard" && <WallboardPage />}
          {page === "backup" && <BackupPage />}
          {page === "zionvm" && <ZionVMPage />}
        </ErrorBoundary>
      </AppShell>
    );
  }

  return (
    <ThemeProvider>
      <AuthProvider key={authenticated ? "auth" : "anon"}>
        <ErrorBoundary>{body}</ErrorBoundary>
      </AuthProvider>
    </ThemeProvider>
  );
}

