const LATENCY_METRICS = new Set(["latency_ms", "response_time_ms", "connect_time_ms"]);
const PERFORMANCE_ORDER = ["cpu_load", "memory_used_pct", "disk_used_pct", "temperature_c"] as const;
const PERFORMANCE_SET = new Set<string>(PERFORMANCE_ORDER);

const METRIC_LABELS: Record<string, string> = {
  latency_ms: "Latência (ms)",
  response_time_ms: "Tempo de resposta (ms)",
  connect_time_ms: "Tempo de conexão (ms)",
  packet_loss: "Perda de pacotes (%)",
  cpu_load: "CPU (%)",
  memory_used_pct: "Memória (%)",
  disk_used_pct: "Disco (%)",
  temperature_c: "Temperatura (°C)",
  ups_battery_charge: "UPS bateria (%)",
  ups_load_pct: "UPS carga (%)",
  http_up: "HTTP up",
  https_up: "HTTPS up",
  tcp_up: "TCP up",
  http_status: "HTTP status",
};

const RANGE_PRESETS = [
  { id: "24h", label: "24h", hours: 24, slaDays: 1 },
  { id: "7d", label: "7d", hours: 168, slaDays: 7 },
  { id: "30d", label: "30d", hours: 720, slaDays: 30 },
] as const;

type RangeId = (typeof RANGE_PRESETS)[number]["id"];

function metricLabel(name: string): string {
  if (METRIC_LABELS[name]) return METRIC_LABELS[name];
  if (name.startsWith("custom_oid:")) return `OID ${name.slice("custom_oid:".length)}`;
  return name;
}

function pickDefaultMetric(names: string[], preferred?: string | null): string {
  if (preferred && names.includes(preferred)) return preferred;
  for (const key of PERFORMANCE_ORDER) {
    if (names.includes(key)) return key;
  }
  const latency = names.find((n) => LATENCY_METRICS.has(n));
  if (latency) return latency;
  const custom = names.find((n) => n.startsWith("custom_oid:"));
  return custom || names[0] || "latency_ms";
}

function groupMetricNames(names: string[]): { group: string; items: string[] }[] {
  const perf = PERFORMANCE_ORDER.filter((n) => names.includes(n));
  const latency = names.filter((n) => LATENCY_METRICS.has(n) || n === "packet_loss");
  const other = names.filter((n) => !PERFORMANCE_SET.has(n) && !LATENCY_METRICS.has(n) && n !== "packet_loss");
  const groups: { group: string; items: string[] }[] = [];
  if (perf.length) groups.push({ group: "Performance", items: [...perf] });
  if (latency.length) groups.push({ group: "Latência / disponibilidade", items: latency });
  if (other.length) groups.push({ group: "Outras", items: other.sort() });
  return groups;
}

export default function DeviceMetricsTab({
  deviceId,
  preferredMetric,
  defaultRange = "24h",
}: {
  deviceId: number;
  preferredMetric?: string | null;
