  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("SentinelAI UI error:", error, info);
  }

  render() {
    if (this.state.error) {
      return (
        <div className="sa-ops-banner sa-ops-banner-error" role="alert" style={{ margin: "1.25rem" }}>
          <div className="sa-ops-banner-fx" aria-hidden>
            <span className="sa-ops-banner-fx-grid" />
            <span className="sa-ops-banner-fx-scan" />
            <span className="sa-ops-banner-fx-pulse" />
          </div>
          <div className="sa-ops-banner-rail" aria-hidden />
          <div className="sa-ops-banner-icon" aria-hidden>
            !
          </div>
          <div className="sa-ops-banner-body">
            <strong className="sa-ops-banner-title">Erro na interface</strong>
            <div className="sa-ops-banner-text">{this.state.error.message}</div>
            <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
              <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" onClick={() => this.setState({ error: null })}>
                Tentar novamente
              </button>
              <button type="button" className="sa-btn sa-btn-secondary sa-btn-sm" onClick={() => window.location.reload()}>
