      );
    }
    return this.props.children;
  }
}

import { useMemo } from "react";

export interface FleetSparkPoint {
  t: string;
  v: number | null;
  n?: number;
}

interface FleetSparklineProps {
  label: string;
  points: FleetSparkPoint[];
  color?: string;
  unit?: string;
}

function buildPath(points: FleetSparkPoint[], width: number, height: number): string {
  const vals = points.map((p) => (p.v == null || Number.isNaN(p.v) ? null : p.v));
  const finite = vals.filter((v): v is number => v != null);
  if (finite.length < 2) return "";
  const min = Math.min(...finite);
  const max = Math.max(...finite);
  const span = max - min || 1;
  const step = width / Math.max(1, points.length - 1);
  let d = "";
  points.forEach((p, i) => {
    if (p.v == null || Number.isNaN(p.v)) return;
    const x = i * step;
    const y = height - ((p.v - min) / span) * (height - 4) - 2;
    d += d ? ` L ${x.toFixed(1)} ${y.toFixed(1)}` : `M ${x.toFixed(1)} ${y.toFixed(1)}`;
  });
  return d;
}

export default function FleetSparkline({
  label,
  points,
  color = "var(--sa-primary)",
  unit = "%",
}: FleetSparklineProps) {
  const latest = useMemo(() => {
    for (let i = points.length - 1; i >= 0; i -= 1) {
      if (points[i]?.v != null) return points[i].v as number;
    }
    return null;
  }, [points]);

  const path = useMemo(() => buildPath(points, 120, 36), [points]);

  return (
    <div className="sa-fleet-spark">
      <div className="sa-fleet-spark-head">
        <span className="sa-fleet-spark-label">{label}</span>
        <strong className="sa-fleet-spark-value">
          {latest == null ? "—" : `${Math.round(latest)}${unit}`}
        </strong>
      </div>
      <svg className="sa-fleet-spark-svg" viewBox="0 0 120 36" preserveAspectRatio="none" aria-hidden>
        <path d={path} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      {!path && <span className="sa-fleet-spark-empty">Sem série nas últimas horas</span>}
    </div>
  );
}

