import { useEffect, useState } from "react";
import { ShieldCheck } from "lucide-react";
import { disableMfa, enableMfa, fetchMe, formatApiError, setupMfa } from "../api/client";

export default function MfaSettingsPanel() {
  const [enabled, setEnabled] = useState(false);
  const [secret, setSecret] = useState<string | null>(null);
  const [qr, setQr] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    fetchMe()
      .then((me) => setEnabled(Boolean(me.mfa_enabled)))
      .catch(() => undefined);
  }, []);

  async function handleSetup() {
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      const data = await setupMfa();
      setSecret(data.secret);
      setQr(data.qr_png_base64);
      setEnabled(false);
      setMessage("Escaneie o QR no autenticador e confirme com o código de 6 dígitos.");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  }

  async function handleEnable() {
    setBusy(true);
    setError(null);
    try {
      await enableMfa(code);
      setEnabled(true);
      setSecret(null);
      setQr(null);
      setCode("");
      setMessage("MFA ativado. O próximo login pedirá o código TOTP.");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  }

  async function handleDisable() {
    setBusy(true);
    setError(null);
    try {
      await disableMfa(password, code);
      setEnabled(false);
      setSecret(null);
      setQr(null);
      setCode("");
      setPassword("");
      setMessage("MFA desativado.");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="sa-card sa-users-create">
      <div className="sa-users-fx" aria-hidden>
        <span className="sa-users-fx-grid" />
        <span className="sa-users-fx-scan" />
      </div>
      <div className="sa-card-header sa-users-header">
        <div>
          <h3>
            <ShieldCheck size={16} style={{ marginRight: 8, verticalAlign: "middle" }} />
            MFA TOTP (minha conta)
          </h3>
        </div>
        <span className={`sa-users-badge${enabled ? " sa-users-ldap-on" : ""}`}>
          {enabled ? "ativo" : "inativo"}
        </span>
      </div>

      <div className="sa-card-body sa-stack" style={{ position: "relative", zIndex: 1 }}>
        {message && <div className="sa-users-toast" role="status">{message}</div>}
        {error && <div className="sa-alert sa-alert-error">{error}</div>}

        {!enabled && !secret && (
          <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" disabled={busy} onClick={handleSetup}>
            {busy ? "Gerando…" : "Configurar MFA"}
          </button>
        )}

        {secret && (
          <div className="sa-stack" style={{ gap: "0.75rem" }}>
            {qr && (
              <img
                src={`data:image/png;base64,${qr}`}
                alt="QR MFA"
                width={180}
                height={180}
                style={{ borderRadius: 8, background: "#fff", padding: 8 }}
              />
            )}
            <p className="sa-text-muted" style={{ fontSize: 12, fontFamily: "ui-monospace, monospace" }}>
              Secret: {secret}
            </p>
            <label className="sa-field" style={{ maxWidth: 220 }}>
              <span className="sa-label">Código de confirmação</span>
              <input
                className="sa-input"
                inputMode="numeric"
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 8))}
                placeholder="123456"
              />
            </label>
            <div style={{ display: "flex", gap: 8 }}>
              <button type="button" className="sa-btn sa-btn-primary sa-btn-sm" disabled={busy || code.length < 6} onClick={handleEnable}>
                Ativar MFA
              </button>
              <button
                type="button"
                className="sa-btn sa-btn-ghost sa-btn-sm"
                onClick={() => {
                  setSecret(null);
                  setQr(null);
                  setCode("");
                }}
              >
                Cancelar
              </button>
            </div>
          </div>
        )}

        {enabled && !secret && (
          <div className="sa-stack" style={{ gap: "0.65rem", maxWidth: 360 }}>
            <label className="sa-field">
              <span className="sa-label">Senha atual</span>
              <input
                className="sa-input"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                autoComplete="current-password"
              />
            </label>
            <label className="sa-field">
              <span className="sa-label">Código MFA</span>
              <input
                className="sa-input"
                inputMode="numeric"
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 8))}
                placeholder="123456"
              />
            </label>
            <button
              type="button"
              className="sa-btn sa-btn-secondary sa-btn-sm"
              disabled={busy || !password || code.length < 6}
              onClick={handleDisable}
            >
              Desativar MFA
            </button>
          </div>
        )}
      </div>
    </section>
  );
}

