import { useMemo } from "react";
import type { Node } from "@xyflow/react";

const SNAP_THRESHOLD = 8;

export interface GuideLine {
  id: string;
  orientation: "horizontal" | "vertical";
  position: number;
}

export function computeAlignmentGuides(
  draggingNode: Node | undefined,
  allNodes: Node[],
): GuideLine[] {
  if (!draggingNode) return [];

  const others = allNodes.filter((n) => n.id !== draggingNode.id && n.type !== "group");
  const dragW = 150;
  const dragH = 80;
  const dragCenterX = draggingNode.position.x + dragW / 2;
  const dragCenterY = draggingNode.position.y + dragH / 2;
  const dragLeft = draggingNode.position.x;
  const dragRight = draggingNode.position.x + dragW;
  const dragTop = draggingNode.position.y;
  const dragBottom = draggingNode.position.y + dragH;

  const guides: GuideLine[] = [];

  for (const other of others) {
    const oW = 150;
    const oH = 80;
    const oCenterX = other.position.x + oW / 2;
    const oCenterY = other.position.y + oH / 2;
    const oLeft = other.position.x;
    const oRight = other.position.x + oW;
    const oTop = other.position.y;
    const oBottom = other.position.y + oH;

    const checks: Array<{ a: number; b: number; orient: "horizontal" | "vertical" }> = [
      { a: dragCenterX, b: oCenterX, orient: "vertical" },
      { a: dragLeft, b: oLeft, orient: "vertical" },
      { a: dragRight, b: oRight, orient: "vertical" },
      { a: dragCenterY, b: oCenterY, orient: "horizontal" },
      { a: dragTop, b: oTop, orient: "horizontal" },
      { a: dragBottom, b: oBottom, orient: "horizontal" },
    ];

    for (const { a, b, orient } of checks) {
      if (Math.abs(a - b) <= SNAP_THRESHOLD) {
        guides.push({ id: `${other.id}-${orient}-${b}`, orientation: orient, position: b });
      }
    }
  }

  return guides;
}

export function AlignmentGuidesOverlay({ guides }: { guides: GuideLine[] }) {
  const unique = useMemo(() => {
    const seen = new Set<string>();
    return guides.filter((g) => {
      const key = `${g.orientation}-${Math.round(g.position)}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }, [guides]);

  if (!unique.length) return null;

  return (
    <svg className="sa-alignment-guides">
      {unique.map((g) =>
        g.orientation === "vertical" ? (
          <line key={g.id} x1={g.position} y1={-5000} x2={g.position} y2={5000} />
        ) : (
          <line key={g.id} x1={-5000} y1={g.position} x2={5000} y2={g.position} />
        ),
      )}
    </svg>
  );
}

