const STATUS_LABELS: Record<string, string> = {
  online: "Online",
  offline: "Offline",
  alert: "Alerta",
  empty: "Sem devices",
};

function statusTone(status: string): "ok" | "warn" | "crit" | "empty" {
  if (status === "online") return "ok";
  if (status === "alert") return "warn";
  if (status === "empty") return "empty";
  return "crit";
}

interface DepartmentListPanelProps {
  departments: DepartmentListItem[];
  loading?: boolean;
  onOpenDepartment: (groupId: number, name: string) => void;
}

export default function DepartmentListPanel({
  departments,
  loading = false,
  onOpenDepartment,
}: DepartmentListPanelProps) {
  const sorted = [...departments].sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));

  return (
    <div className="sa-dept-list-panel sa-dept-list-eng">
      <div className="sa-dept-list-head">
        <div>
          <h4>
            <Building2 size={14} /> Departamentos
          </h4>
        </div>
      </div>

      {loading ? (
        <div className="sa-dept-list-empty">
          <span className="sa-spinner" />
        </div>
      ) : sorted.length === 0 ? (
        <div className="sa-dept-list-empty">
          <Building2 size={22} strokeWidth={1.5} />
          <span>Nenhum departamento no mapa</span>
        </div>
      ) : (
        <ul className="sa-dept-list">
          {sorted.map((dept) => {
            const tone = statusTone(dept.status);
            const pct =
              dept.deviceCount > 0 ? Math.round((dept.onlineCount / dept.deviceCount) * 100) : 0;
            const detail =
              dept.deviceCount === 0
