            return (
              <li key={dept.groupId}>
                <button
                  type="button"
                  className={`sa-dept-list-item sa-dept-list-item-${tone}`}
                  onClick={() => onOpenDepartment(dept.groupId, dept.name)}
                  title={`Abrir submapa — ${dept.name} (${detail})`}
