import { FormEvent, useState } from "react";
import { AlertCircle, KeyRound, Shield } from "lucide-react";
import { changePassword, fetchMe } from "../api/client";

export default function ChangePasswordPage({ onDone }: { onDone: () => void }) {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    setError("");
    if (newPassword !== confirmPassword) {
      setError("A confirmação não coincide com a nova senha");
      return;
    }
    if (newPassword.length < 8) {
      setError("A nova senha deve ter pelo menos 8 caracteres");
      return;
    }
    setLoading(true);
    try {
      await changePassword(currentPassword, newPassword);
      // Confirma no servidor que a flag ficou limpa (evita ecrã preso)
      const me = await fetchMe();
      if (me.must_change_password) {
        setError("A senha foi guardada, mas a sessão ainda exige troca. Faça logout e login de novo.");
        return;
      }
      onDone();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Não foi possível alterar a senha");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="sa-login-page">
      <div className="sa-login-card">
        <div className="sa-login-brand">
          <div className="sa-login-brand-icon">
            <KeyRound size={28} />
          </div>
          <h1>Alterar senha</h1>
          <p>
            Atualize a sua senha para continuar. Depois só será pedida de novo a cada 30 dias.
          </p>
        </div>

        <form className="sa-login-form" onSubmit={handleSubmit}>
          <label className="sa-label">
            Senha atual
            <input
              className="sa-input"
              type="password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              autoComplete="current-password"
              autoFocus
              required
            />
          </label>
          <label className="sa-label">
            Nova senha
            <input
              className="sa-input"
              type="password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              autoComplete="new-password"
              minLength={8}
              required
            />
          </label>
          <label className="sa-label">
            Confirmar nova senha
            <input
              className="sa-input"
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              autoComplete="new-password"
              minLength={8}
              required
            />
          </label>

          {error && (
            <div className="sa-alert sa-alert-error" role="alert">
              <AlertCircle size={16} />
              {error}
            </div>
          )}

          <button type="submit" className="sa-btn sa-btn-primary sa-btn-block" disabled={loading}>
            {loading ? (
              <>
                <span className="sa-spinner" /> A guardar...
              </>
            ) : (
              <>
                <Shield size={16} /> Continuar
              </>
            )}
          </button>
        </form>
      </div>
    </div>
  );
}

