import { useEffect, useMemo, useState } from "react";
import { fetchPublicWallboard, type WallboardPublicPayload } from "../api/client";
import WallboardScreen from "../components/WallboardScreen";

function parseWallboardHash(): { slug: string; token: string } | null {
  const hash = window.location.hash || "";
  // #/wallboard/{slug}?token=...
  const m = hash.match(/^#\/wallboard\/([^/?]+)(?:\?(.*))?$/);
  if (!m) return null;
  const slug = decodeURIComponent(m[1]);
  const params = new URLSearchParams(m[2] || "");
  const token = params.get("token") || "";
  if (!slug || !token) return null;
  return { slug, token };
}

export function isPublicWallboardRoute(): boolean {
  return Boolean(parseWallboardHash());
}

export default function PublicWallboardPage() {
  const route = useMemo(() => parseWallboardHash(), []);
  const [data, setData] = useState<WallboardPublicPayload | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [activeIdx, setActiveIdx] = useState(0);

  useEffect(() => {
    document.body.classList.add("sa-tv-mode");
    return () => document.body.classList.remove("sa-tv-mode");
  }, []);

  useEffect(() => {
    if (!route) {
      setError("URL inválida. Use #/wallboard/{slug}?token=...");
      return;
    }
    let cancelled = false;
    const load = () => {
      fetchPublicWallboard(route.slug, route.token)
        .then((payload) => {
          if (!cancelled) {
            setData(payload);
            setError(null);
          }
        })
        .catch((e) => {
          if (!cancelled) setError(String(e));
        });
    };
    load();
    const refresh = window.setInterval(load, 60_000);
    return () => {
      cancelled = true;
      window.clearInterval(refresh);
    };
  }, [route]);

  useEffect(() => {
    if (!data || data.panels.length <= 1) return;
    const id = window.setInterval(() => {
      setActiveIdx((i) => (i + 1) % data.panels.length);
    }, Math.max(5, data.rotate_seconds) * 1000);
    return () => window.clearInterval(id);
  }, [data]);

  if (error) {
    return (
      <div className="sa-wallboard sa-wallboard-hc sa-loading-row-compact sa-flex-col">
        <h1>NOC Wall</h1>
        <p>{error}</p>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="sa-wallboard sa-wallboard-hc sa-loading-row sa-loading-row-compact">
        <span className="sa-spinner" /> Carregando wallboard…
      </div>
    );
  }

  const panels = data.panels.length ? [data.panels[activeIdx % data.panels.length]] : [];

  return (
    <WallboardScreen
      title={data.name}
      overview={data.overview}
      panels={panels}
      highContrast={data.high_contrast}
      rotateHint={
        data.panels.length > 1
          ? `Auto-rotate ${data.rotate_seconds}s · ${activeIdx + 1}/${data.panels.length}`
          : "TV mode · só-leitura"
      }
    />
  );
}

