import type { Edge, Node } from "@xyflow/react";

export async function layoutElk(nodes: Node[], edges: Edge[]): Promise<Node[]> {
  const ELK = (await import("elkjs/lib/elk.bundled.js")).default;
  const elk = new ELK();

  const elkGraph = {
    id: "root",
    layoutOptions: {
      "elk.algorithm": "layered",
      "elk.direction": "DOWN",
      "elk.spacing.nodeNode": "80",
      "elk.layered.spacing.nodeNodeBetweenLayers": "100",
      "elk.edgeRouting": "ORTHOGONAL",
    },
    children: nodes
      .filter((n) => n.type !== "group")
      .map((n) => ({
        id: n.id,
        width: 150,
        height: 80,
      })),
    edges: edges.map((e) => ({ id: e.id, sources: [e.source], targets: [e.target] })),
  };

  const layouted = await elk.layout(elkGraph);
  const positions = new Map<string, { x: number; y: number }>();
  for (const child of layouted.children ?? []) {
    positions.set(child.id, { x: child.x ?? 0, y: child.y ?? 0 });
  }

  return nodes.map((n) => {
    const pos = positions.get(n.id);
    if (!pos) return n;
    return { ...n, position: pos };
  });
}

/** Spoken welcome for Canon Engine avatar (Product AI / NOC Copilot). */
export const SENTINEL_WELCOME_SCRIPT =
  "Bem-vindo ao SentinelAI. Sou uma inteligência artificial integrada à plataforma e tenho acesso ao inventário, topologia, monitoramento, eventos, métricas e dispositivos da sua infraestrutura. Posso identificar problemas, sugerir soluções, localizar equipamentos, analisar desempenho e auxiliar sua equipe de operações. O que você deseja analisar?";

export const SENTINEL_WELCOME_AUDIO_SRC = "/audio/sentinel-welcome.wav";

let sharedAudio: HTMLAudioElement | null = null;
let voicesWarmed = false;

function getSharedAudio(): HTMLAudioElement {
  if (!sharedAudio) {
    sharedAudio = new Audio(SENTINEL_WELCOME_AUDIO_SRC);
    sharedAudio.preload = "auto";
    sharedAudio.loop = false;
  }
  sharedAudio.loop = false;
  return sharedAudio;
}

/** Warm decode so the first click is less likely to stall. */
export function preloadSentinelWelcomeAudio(): void {
  if (typeof window === "undefined") return;
  try {
    getSharedAudio().load();
  } catch {
    /* ignore */
  }
  if (window.speechSynthesis && !voicesWarmed) {
    voicesWarmed = true;
    window.speechSynthesis.getVoices();
    window.speechSynthesis.addEventListener("voiceschanged", () => {
      window.speechSynthesis.getVoices();
    });
  }
}

function pickMalePtBrVoice(): SpeechSynthesisVoice | null {
  const voices = window.speechSynthesis.getVoices();
  if (!voices.length) return null;
  const ranked = [
    (v: SpeechSynthesisVoice) => /daniel/i.test(v.name) && /^pt/i.test(v.lang),
    (v: SpeechSynthesisVoice) => /^pt[-_]BR$/i.test(v.lang) && /male|homem|daniel|ricardo|felipe/i.test(v.name),
    (v: SpeechSynthesisVoice) => /^pt[-_]BR$/i.test(v.lang) && !/female|maria|zira|helena|francisca/i.test(v.name),
    (v: SpeechSynthesisVoice) => /^pt\b/i.test(v.lang) && !/female|maria|zira|helena|francisca/i.test(v.name),
  ];
  for (const match of ranked) {
    const found = voices.find(match);
    if (found) return found;
  }
  return voices.find((v) => /^pt[-_]BR$/i.test(v.lang)) ?? null;
}

function speakWithWebSpeech(): boolean {
  if (typeof window === "undefined" || !window.speechSynthesis) return false;
  try {
    window.speechSynthesis.cancel();
    window.speechSynthesis.resume();
    const utterance = new SpeechSynthesisUtterance(SENTINEL_WELCOME_SCRIPT);
    utterance.lang = "pt-BR";
    utterance.rate = 1;
    utterance.pitch = 0.95;
    utterance.volume = 1;
    const voice = pickMalePtBrVoice();
    if (voice) utterance.voice = voice;
    window.speechSynthesis.speak(utterance);
    return true;
  } catch {
    return false;
  }
}

/**
 * Plays the male pt-BR welcome once per click (no loop).
 * Finished audio does not auto-replay — only a new click starts it again.
 * A new click while playing restarts from the beginning (one shot).
 * Must be called synchronously inside the click handler.
 */
export function playSentinelWelcomeAudio(): void {
  if (typeof window === "undefined") return;

  // Stop any leftover speech fallback from a previous click.
  try {
    window.speechSynthesis?.cancel();
  } catch {
    /* ignore */
  }

  const audio = getSharedAudio();
  audio.loop = false;

  try {
    audio.pause();
    audio.currentTime = 0;
  } catch {
    /* ignore seek errors before metadata */
  }

  const playPromise = audio.play();
  if (playPromise && typeof playPromise.then === "function") {
    playPromise.catch(() => {
      speakWithWebSpeech();
    });
    return;
  }

  speakWithWebSpeech();
}

